    {
      "key": "headline",
      "text": "Keep {arm:September}: both challengers cost more per reply while regressing on character adherence."
    },
    {
      "key": "lede",
      "text": "{arm:September} delivers the highest adherence pass rate at {pass_rate.September|pct} for {cost_per_1k.September|usd} per 1,000 replies. Neither candidate beats the baseline on persona fidelity or cost."
    },
    {
      "key": "confidence.caveats.late:aspect",
      "text": "The asked aspect was declared late, material only if evaluated dimensions did not reflect operational objectives."
    },
    {
      "key": "confidence.caveats.late:control",
      "text": "The control baseline was designated late, material only if another variant served as the historical production baseline."
    },
    {
      "key": "confidence.caveats.judge_uncalibrated",
      "text": "The judge has insufficient calibration, material only if relative cross-arm rankings invert under human review."
    },
    {
      "key": "decision.recommendation",
      "text": "Retain {arm:September} in production. It achieves {pass_rate.September|pct} adherence while serving traffic at {cost_per_1k.September|usd} per 1,000 replies."
    },
    {
      "key": "decision.why_not",
      "text": "{arm:1017} increases costs by {cost.uplift.1017|usd} per reply and regresses on holds_character by {contrast.1017.persona.holds_character.delta|abs|pts} points ({contrast.1017.persona.holds_character.interval|pts}); {arm:qwen3.8-flash} drops adherence pass rate by {reading.qwen3.8-flash.change|abs|pts} points ({reading.qwen3.8-flash.interval|pts}) at higher cost."
    },
    {
      "key": "decision.watch",
      "text": "Earlier insights noted {arm:qwen3.8-flash} lowers production costs, but production-replicating spend increased. Reasoning ratio varied from {reasoning_ratio.September|pct} down to {reasoning_ratio.1017|pct}, confounding model comparisons. Two degraded runs excluded one cell each."
    },
    {
      "key": "decision.next",
      "text": "Re-test candidate checkpoints only if prompt directives explicitly mitigate the off_lane character drop observed across all models."
    },
    {
      "key": "summary.0.title",
