    {
      "key": "method.6.text",
      "text": "Token counts and raw llm_calls telemetry were excluded from report bundles."
    },
    {
      "key": "explore.title",
      "text": "Margin sensitivity"
    },
    {
      "key": "explore.recomputes",
      "text": "No margin threshold flips the decision to a candidate because {arm:September} dominates on both cost and quality. {arm:1017} drops out of margin if margin is set below {flip_margin.1017|pts} points; {arm:qwen3.8-flash} drops out below {flip_margin.qwen3.8-flash|pts} points."
    },
    {
      "key": "explore.controls.margin_slider.title",
      "text": "Adherence margin threshold"
    }
